/* ---------- the shared contract: where each module shows up ---------- */
const FEEDS=['Today','Calendar','Search','Review'];
function feedsOf(hub,t){const f=new Set(['Search','Review']),ti=TOOL_INTRO[t.id]||t.intro;(ti&&ti.shows||[]).forEach(([w])=>{const n=TI_W[w][1];if(n==='Weekly review')f.add('Review');else if(n==='Today'||n==='Calendar')f.add(n);});if(t.tpl==='checklist'||t.dueKey)f.add('Today');if(t.dueKey&&t.after)f.add('Calendar');if(isPinned(hub,t.id))f.add('Today');return FEEDS.filter(x=>f.has(x));}
