const modWord=({t,n})=>`${n} ${n===1?t.word:t.word.replace(/(s|sh|ch|x)$/,'$1e')+'s'}`.replace(/ys$/,'ies').replace(/([^aeiou])ies$/,'$1ies');
function modWeekCard(a,b){const l=modWeek(a,b);if(!l.length)return null;return el('div',{class:'card',style:'padding:14px 16px'},el('div',{class:'lbl'},'From your modules'),el('div',{class:'chips',style:'margin-top:8px'},l.slice(0,10).map(x=>el('button',{class:'chip',onclick:()=>App.go('tool',{hub:x.hub,tool:x.t.id})},modWord(x)))));}
/* Today: anything due from template modules */
function tplDueRows(dk,rowOf,off){const out=[];if(dk!==todayK())return out;if(!off('Finances').includes('bills'))ofType('Finances','bills','sub').forEach(x=>{if(x.f.gone||!x.f.trial||x.f.trial<dk)return;const n=daysBetween(dk,x.f.trial);if(n>3)return;out.push(rowOf('tr'+x.id,false,null,`${x.f.what} free trial ends ${n===0?'today':n===1?'tomorrow':`in ${n} days`}`,`Bills · ${money(+x.f.amount||0)} a month after`,()=>App.go('tool',{hub:'Finances',tool:'bills'}),true));});Object.keys(HUBS).concat((get.settings().customMods||[]).map(m=>m.hub)).filter((h,i,a)=>a.indexOf(h)===i).forEach(hub=>toolsOf(hub).forEach(t=>{if(!t.tpl||off(hub).includes(t.id))return;
  if(t.tpl==='checklist')entries(hub,t.id).forEach(x=>{const dn=x.f.last===dk,ds=dueState(x);if(!dn&&!ds.over)return;out.push(rowOf('dt'+x.id,dn,tk(dn,v=>{if(v){x.f.prev=x.f.last||null;x.f.last=dk;x.f.logs=[...(x.f.logs||[]),dk];}else{x.f.last=x.f.prev||null;}put(x);},`${x.f.what} done`),x.f.what,dn?t.name:`${t.name} · ${ds.txt||'due'}`,()=>App.go('tool',{hub,tool:t.id}),!dn));});
  if(t.dueKey)entries(hub,t.id).forEach(x=>{const d=x.f[t.dueKey];if(!d||(d<dk&&!t.dueOverdue)||t.closed(x))return;const n=daysBetween(dk,d);if(n>(x.f.remind!=null&&x.f.remind!==''?+x.f.remind:(t.dueWin??30)))return;out.push(rowOf('dk'+x.id,false,null,t.feedTitle?t.feedTitle(x):x.f.what,`${t.name} · ${n<0?`${dCount(-n,'day')} ago`:n===0?'today':n===1?'tomorrow':`in ${n} days`}`,()=>t.onOpen?t.onOpen(x,hub,t):entrySheet(hub,t,x),n<=7));});
  if(t.extraDue)t.extraDue(dk,hub).forEach(r=>out.push(rowOf(r.id,false,null,r.title,r.sub,r.open,!!r.late)));
  if(t.tpl==='log'&&t.schedFeed)entries(hub,t.id).forEach(x=>{if(x.f.date!==dk||!(x.createdAt&&k(new Date(x.createdAt))<dk))return;out.push(rowOf('dl'+x.id,false,null,x.f.what,`${t.name} · today`,()=>entrySheet(hub,t,x),false));});}));return out;}

/* ---------- pin a module to Today ---------- */
const pinKey=(hub,id)=>`${hub}|${id}`;
const isPinned=(hub,id)=>(get.settings().todayPins||[]).includes(pinKey(hub,id));
function togglePin(hub,t){const l=(get.settings().todayPins||[]).slice(),key=pinKey(hub,t.id),i=l.indexOf(key);if(i>=0)l.splice(i,1);else{if(l.length>=6){toast('Six pins at most. Unpin one first.');return;}l.push(key);if(!toolOn(hub,t.id))setToolOn(hub,t.id,true);}setSettings({todayPins:l});toast(i>=0?`${t.name} unpinned`:`${t.name} pinned to Today`,()=>{setSettings({todayPins:(get.settings().todayPins||[]).filter(x=>x!==key).concat(i>=0?[key]:[])});});}
function pinsCard(dk){if(dk!==todayK())return null;const l=(get.settings().todayPins||[]).map(x=>{const[hub,id]=x.split('|');const t=toolOf(hub,id);return t&&toolOn(hub,id)?[hub,t]:null;}).filter(Boolean);if(!l.length)return null;
  return el('section',{class:'tpins'},el('div',{class:'lbl dhead',style:'margin:2px 4px 6px'},'Pinned'),el('div',{class:'hrail'},l.map(([hub,t])=>{let n;try{n=toolTile(hub,t);}catch(e){n=el('button',{class:'tc',onclick:()=>App.go('tool',{hub,tool:t.id})},el('span',{class:'tn'},t.name));}withPress(n,(x,y)=>openMenu(x,y,[{label:'Open',icon:'arrow',onclick:()=>App.go('tool',{hub,tool:t.id})},{label:'Unpin from Today',icon:'pin',onclick:()=>togglePin(hub,t)}]));return n;})));}

/* ---------- export any module ---------- */
function toolFieldsAll(t){const out=[],seen=new Set();const add=fs=>(fs||[]).forEach(f=>{if(!seen.has(f.id)){seen.add(f.id);out.push(f);}});add(t.fields);Object.values(t.types||{}).forEach(d=>add(d.fields));return out;}
function exportTool(hub,t){const l=entries(hub,t.id);if(!l.length){toast(`No ${t.word}s to export yet`);return;}const fs=toolFieldsAll(t),hasT=!!t.types,q=v=>{if(v==null)return'""';if(typeof v==='object')v=Array.isArray(v)?v.map(x=>typeof x==='object'?(x.t||x.what||x.date||JSON.stringify(x)):x).join('; '):Object.keys(v).length+' entries';return `"${String(v).replace(/"/g,'""')}"`;};
  const head=[...(hasT?['Type']:[]),...fs.map(f=>f.label.replace(/\s*\(.*\)$/,'')),'Added'],body=l.map(x=>[...(hasT?[q(x.f.t?((t.types[x.f.t]||{}).word||x.f.t):t.word)]:[]),...fs.map(f=>q(x.f[f.id])),q(k(new Date(x.createdAt||Date.now())))].join(','));
  saveFile(`Life-OS-${t.name.replace(/[^\w]+/g,'-')}-${todayK()}.csv`,[head.map(h=>q(h)).join(','),...body].join('\n'));}
function modMenu(hub,t,x,y,{onPage=false}={}){openMenu(x,y,[onPage?null:{label:'Open',icon:'arrow',onclick:()=>App.go('tool',{hub,tool:t.id})},{label:isPinned(hub,t.id)?'Unpin from Today':'Pin to Today',icon:'pin',onclick:()=>togglePin(hub,t)},{label:'Export as spreadsheet',icon:'share',onclick:()=>exportTool(hub,t)},t.id==='spending'?{label:'Import from a bank file',icon:'plus',onclick:()=>bankImport()}:null,t.custom?{label:'Edit module',icon:'edit',onclick:()=>modSheet((get.settings().customMods||[]).find(m=>m.id===t.id))}:null,t.custom?{label:'Delete module',icon:'trash',danger:true,onclick:()=>delMod(hub,t)}:{label:'Turn off',icon:'x',onclick:()=>{setToolOn(hub,t.id,false);toast(`${t.name} is off`,()=>setToolOn(hub,t.id,true));if(onPage)App.back('area');}}]);}
/* add the module menu to every module page header */
